  'home.why.f1p': { en: 'Every tip is archived and settled against real results. No cherry-picking — win rate and ROI come from graded bets only.', es: 'Cada pronóstico se archiva y se liquida con resultados reales. Sin trampas: el acierto y el ROI salen solo de apuestas liquidadas.', pt: 'Cada palpite é arquivado e liquidado com resultados reais. Sem seleção conveniente — acerto e ROI vêm apenas de apostas liquidadas.', de: 'Jeder Tipp wird archiviert und an echten Ergebnissen abgerechnet. Kein Rosinenpicken — Trefferquote und ROI stammen nur aus abgerechneten Wetten.' },
  'home.why.f2h': { en: 'Honest bookmaker reviews', es: 'Reseñas honestas', pt: 'Análises honestas', de: 'Ehrliche Bewertungen' },
  'home.why.f2p': { en: 'Operators are scored on six criteria and ranked by the score — nobody buys a higher position.', es: 'Los operadores se puntúan con seis criterios y se ordenan por nota: nadie compra una posición mejor.', pt: 'Os operadores são avaliados em seis critérios e ranqueados pela nota — ninguém compra posição.', de: 'Anbieter werden nach sechs Kriterien bewertet und danach gereiht — niemand kauft sich eine bessere Position.' },
  'home.why.f3h': { en: 'Always free', es: 'Siempre gratis', pt: 'Sempre grátis', de: 'Immer kostenlos' },
  'home.why.f3p': { en: 'All daily predictions, the screener and analysis are completely free. No paywalls, no premium upsells.', es: 'Todos los pronósticos diarios, el screener y los análisis son gratis. Sin muros de pago ni versiones premium.', pt: 'Todos os palpites diários, o screener e as análises são grátis. Sem paywall, sem plano premium.', de: 'Alle täglichen Prognosen, der Screener und die Analysen sind komplett kostenlos. Keine Paywalls, kein Premium.' },
