  'home.news.makes': { en: 'Our model makes {tip} the value play at {price} — full reasoning, odds comparison and confidence inside.', es: 'Nuestro modelo señala {tip} como la apuesta de valor a cuota {price}: análisis completo, comparativa de cuotas y confianza dentro.', pt: 'Nosso modelo aponta {tip} como a aposta de valor na odd {price} — análise completa, comparação de odds e confiança na página.', de: 'Unser Modell sieht {tip} als Value-Wette zur Quote {price} — komplette Begründung, Quotenvergleich und Vertrauen im Artikel.' },
